//! Obligation P32 frontier: certify prerequisite closure before any bounded research effect.
use bioprism_ids::ContentHash;
use serde::{Deserialize, Serialize};
use serde_json::json;
use std::collections::BTreeSet;
use thiserror::Error;
pub const FEATURE_ID:&str="AFA-obligation-P32-F01";pub const CONTRACT_VERSION:&str="obligation-local-closure-gate/1.0";pub const CONTENT_TYPE:&str="application/vnd.aurora.obligation.closure-gate-card-1+json";pub const BOUNDARY:&str="preclinical-research-only; no human-subject or clinical-source data; no diagnosis, treatment, triage, enrollment, or clinical decisions";
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct ObligationPredicate4{pub obligation_id:String,pub action_id:String,pub prerequisite:String,pub evidence_digest:ContentHash,pub satisfied:bool,pub influence:String,pub policy_epoch:u64,pub local:bool,pub aggregate_only:bool,pub negative_result:bool}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct ClosureGateRequest4{pub request_id:String,pub purpose:String,pub predicates:Vec<ObligationPredicate4>,pub required_obligation_order:Vec<String>,pub required_action_order:Vec<String>,pub policy_allowed:bool,pub protected_closure:bool,pub signed_approval:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub replay_identity:ContentHash,pub adversarial_events:Vec<String>,pub action_budget:u32,pub action_count:u32,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct ClosureGateArtifact4{pub artifact_id:String,pub content_type:String,pub content_hash:ContentHash,pub semantic_loss:Vec<String>,pub predicate_digests:Vec<ContentHash>,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct ClosureGateCard7{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub mode:String,pub scale:String,pub request_id:String,pub purpose:String,pub disposition:String,pub predicate_order:Vec<String>,pub satisfied_order:Vec<String>,pub unsatisfied_order:Vec<String>,pub unknown_order:Vec<String>,pub omitted_order:Vec<String>,pub obligation_order:Vec<String>,pub action_order:Vec<String>,pub influence_order:Vec<String>,pub negative_evidence_order:Vec<String>,pub replay_identity:ContentHash,pub closure_digest:ContentHash,pub artifact:ClosureGateArtifact4,pub effect_receipts:Vec<String>,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum ClosureGateError{#[error("invalid closure-gate request: {0}")]Invalid(String),#[error("closure-gate card failed validation: {0}")]Output(String)}
fn ordered(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}fn digest(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}fn nonempty(v:&str)->bool{!v.trim().is_empty()}
pub fn manifest(id:&str,version:&str,scale:&str,mode:&str)->serde_json::Value{json!({"schema_version":"1.0.0","capability_id":id,"version":version,"owner_crate":"obligation","consumers":["action gate","token budget controller","workflow compiler","release auditor"],"behavior":format!("certify obligation prerequisite closure at {scale} ({mode})"),"value":"blocks high-regret actions when prerequisites are missing, unknown, stale, or contradictory","input_schema":"ClosureGateRequest4@1","output_schema":"ClosureGateCard7@1","effects":["emit:closure-gate-card","retain:unmet-obligations","block:unsafe-action"],"permissions":["read:local-obligation-predicates"],"determinism":"byte_stable","autonomy_tier":"A1","boundary":BOUNDARY})}
impl ClosureGateCard7{pub fn validate(&self)->Result<(),ClosureGateError>{if self.schema_version!="1.0.0"||!nonempty(&self.contract_version)||!nonempty(&self.feature_id)||!nonempty(&self.mode)||!nonempty(&self.scale)||!nonempty(&self.request_id)||!nonempty(&self.purpose)||self.boundary!=BOUNDARY||!self.raw_data_local||!self.aggregate_only||self.predicate_order.is_empty()||!ordered(&self.predicate_order)||!ordered(&self.satisfied_order)||!ordered(&self.unsatisfied_order)||!ordered(&self.unknown_order)||!ordered(&self.omitted_order)||!ordered(&self.obligation_order)||!ordered(&self.action_order)||!ordered(&self.influence_order)||!ordered(&self.negative_evidence_order)||!digest(&self.replay_identity)||!digest(&self.closure_digest)||self.artifact.content_type!=CONTENT_TYPE||self.artifact.content_hash!=self.closure_digest||self.artifact.boundary!=BOUNDARY{return Err(ClosureGateError::Output("closure identity, ordering, locality, digest, or artifact is invalid".into()))}let ids=BTreeSet::from_iter(self.predicate_order.iter().cloned());let states=self.satisfied_order.iter().chain(&self.unsatisfied_order).chain(&self.unknown_order).chain(&self.omitted_order).cloned().collect::<Vec<_>>();if ids.len()!=self.predicate_order.len()||states.len()!=ids.len()||BTreeSet::from_iter(states)!=ids{return Err(ClosureGateError::Output("predicate states do not partition".into()))}Ok(())}}
pub fn certify(request:&ClosureGateRequest4,id:&str,version:&str,scale:&str,mode:&str)->Result<ClosureGateCard7,ClosureGateError>{if !nonempty(&request.request_id)||!nonempty(&request.purpose)||request.predicates.is_empty()||request.required_obligation_order.is_empty()||request.required_action_order.is_empty()||!digest(&request.replay_identity)||request.boundary!=BOUNDARY||!request.raw_data_local||!request.aggregate_only||!ordered(&request.required_obligation_order)||!ordered(&request.required_action_order)||!ordered(&request.adversarial_events){return Err(ClosureGateError::Invalid("closure identity, requirements, digest, ordering, locality, or boundary is invalid".into()))}let mut rows=request.predicates.clone();rows.sort_by(|a,b|a.obligation_id.cmp(&b.obligation_id));let mut seen=BTreeSet::new();let mut order=Vec::new();let mut satisfied=BTreeSet::new();let mut unsatisfied=BTreeSet::new();let mut unknown=BTreeSet::new();let mut omitted=BTreeSet::new();let mut obligations=BTreeSet::new();let mut actions=BTreeSet::new();let mut influences=BTreeSet::new();let mut negative=BTreeSet::new();let mut digests=BTreeSet::new();for p in &rows{if !seen.insert(p.obligation_id.clone())||!nonempty(&p.obligation_id)||!nonempty(&p.action_id)||!nonempty(&p.prerequisite)||!digest(&p.evidence_digest)||!nonempty(&p.influence)||!p.local||!p.aggregate_only{return Err(ClosureGateError::Invalid("predicate identity, evidence, influence, or locality is invalid".into()))}order.push(p.obligation_id.clone());obligations.insert(p.obligation_id.clone());actions.insert(p.action_id.clone());influences.insert(p.influence.clone());digests.insert(p.evidence_digest.clone());if p.negative_result{negative.insert(format!("{}:negative-result",p.obligation_id));}if p.policy_epoch==0{unknown.insert(p.obligation_id.clone());}else if !p.satisfied{unsatisfied.insert(p.obligation_id.clone());}else if !request.required_obligation_order.contains(&p.obligation_id)||!request.required_action_order.contains(&p.action_id){unsatisfied.insert(p.obligation_id.clone());}else if p.evidence_digest==request.replay_identity{omitted.insert(p.obligation_id.clone());}else{satisfied.insert(p.obligation_id.clone());}}let global=!request.policy_allowed||!request.protected_closure||!request.signed_approval||!request.raw_data_local||!request.aggregate_only||!request.adversarial_events.is_empty()||request.action_count>request.action_budget;if global{omitted.extend(order.iter().cloned());satisfied.clear();unsatisfied.clear();unknown.clear();}let missing=!request.required_obligation_order.iter().all(|o|obligations.contains(o))||!request.required_action_order.iter().all(|a|actions.contains(a));let disposition=if global{"blocked"}else if missing{"unknown"}else if !unsatisfied.is_empty()||!unknown.is_empty()||!omitted.is_empty(){"partial"}else{"qualified"};let mut payload=json!({"schema_version":"1.0.0","contract_version":version,"feature_id":id,"mode":mode,"scale":scale,"request_id":request.request_id,"purpose":request.purpose,"disposition":disposition,"predicate_order":order,"satisfied_order":satisfied.into_iter().collect::<Vec<_>>(),"unsatisfied_order":unsatisfied.into_iter().collect::<Vec<_>>(),"unknown_order":unknown.into_iter().collect::<Vec<_>>(),"omitted_order":omitted.into_iter().collect::<Vec<_>>(),"obligation_order":obligations.into_iter().collect::<Vec<_>>(),"action_order":actions.into_iter().collect::<Vec<_>>(),"influence_order":influences.into_iter().collect::<Vec<_>>(),"negative_evidence_order":negative.into_iter().collect::<Vec<_>>(),"replay_identity":request.replay_identity,"raw_data_local":true,"aggregate_only":true,"boundary":BOUNDARY});let hash=ContentHash::of_value(&payload).map_err(|e|ClosureGateError::Output(e.to_string()))?;payload["closure_digest"]=json!(hash);payload["artifact"]=json!({"artifact_id":format!("obligation-closure:{}",request.request_id),"content_type":CONTENT_TYPE,"content_hash":hash,"semantic_loss":payload["omitted_order"],"predicate_digests":digests.into_iter().collect::<Vec<_>>(),"boundary":BOUNDARY});payload["effect_receipts"]=json!(if disposition=="qualified"{vec![format!("emit:closure-gate:{}",request.request_id)]}else{vec!["block:unsafe-action".to_string()]});let out:ClosureGateCard7=serde_json::from_value(payload).map_err(|e|ClosureGateError::Output(e.to_string()))?;out.validate()?;Ok(out)}

#[cfg(test)]
mod tests { use super::*;
    fn request(adversarial_events: Vec<String>) -> ClosureGateRequest4 { ClosureGateRequest4 { request_id:"r1".into(), purpose:"verify preflight".into(), predicates:vec![ObligationPredicate4{obligation_id:"o1".into(),action_id:"a1".into(),prerequisite:"evidence-ready".into(),evidence_digest:ContentHash::of_bytes(b"evidence"),satisfied:true,influence:"high".into(),policy_epoch:1,local:true,aggregate_only:true,negative_result:false}], required_obligation_order:vec!["o1".into()], required_action_order:vec!["a1".into()], policy_allowed:true, protected_closure:true, signed_approval:true, raw_data_local:true, aggregate_only:true, replay_identity:ContentHash::of_bytes(b"replay"), adversarial_events, action_budget:2, action_count:1, boundary:BOUNDARY.into() } }
    #[test] fn qualifies_complete_predicate() { let card=certify(&request(vec![]),FEATURE_ID,CONTRACT_VERSION,"local single-study","inference").expect("qualified"); assert_eq!(card.disposition,"qualified"); assert_eq!(card.satisfied_order,["o1"]); card.validate().expect("valid card"); }
    #[test] fn blocks_adversarial_event() { let card=certify(&request(vec!["prompt-injection".into()]),FEATURE_ID,CONTRACT_VERSION,"local single-study","inference").expect("blocked receipt"); assert_eq!(card.disposition,"blocked"); assert_eq!(card.effect_receipts,["block:unsafe-action"]); }
}
